spec.setup_code:
var A = 0.26;
var PI2 = Math.PI * 2;
function qx(tau) { return 0.05 + 0.9 * tau; }
function qy(tau) { return 0.5 - A * Math.sin(PI2 * 1.1 * tau + 0.4); }
function dqx(tau) { return 0.9; }
function dqy(tau) { return -A * PI2 * 1.1 * Math.cos(PI2 * 1.1 * tau + 0.4); }
var aa = 1.6;
var N = 5;
var E = [[qx(0), qy(0)]];
for (var k = 0; k < N; k++) {
  var tau = k / N, h = 1 / N, p = E[k];
  var fx = dqx(tau) + aa * (p[0] - qx(tau));
  var fy = dqy(tau) + aa * (p[1] - qy(tau));
  E.push([p[0] + h * fx, p[1] + h * fy]);
}
function ease(x) { x = Math.max(0, Math.min(1, x)); return x * x * (3 - 2 * x); }
return {
  draw: function (ctx, width, height, time, dt) {
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, width, height);
    var T = time % 10;
    var L = 40, R = width - 40, Tp = 80, B = height - 70;
    var W = R - L, H = B - Tp;
    function X(u) { return L + u * W; }
    function Y(v) { return Tp + v * H; }
    ctx.font = '13px sans-serif';
    ctx.textAlign = 'left';
    ctx.fillStyle = '#1a1a1d';
    ctx.fillText('State space x (2-D slice): noise x_1 at t=1  →  data x_0 at t=0', 16, 24);
    var status = '';
    // true trajectory
    ctx.strokeStyle = '#1a1a1d';
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (var i = 0; i <= 80; i++) {
      var tt = i / 80;
      if (i === 0) ctx.moveTo(X(qx(tt)), Y(qy(tt))); else ctx.lineTo(X(qx(tt)), Y(qy(tt)));
    }
    ctx.stroke();
    // time ticks
    ctx.font = '12px sans-serif';
    for (var m = 0; m <= 4; m++) {
      var ts = m / 4;
      var px = X(qx(ts)), py = Y(qy(ts));
      ctx.fillStyle = '#ffffff';
      ctx.strokeStyle = '#1a1a1d';
      ctx.lineWidth = 1.2;
      ctx.beginPath(); ctx.arc(px, py, 4, 0, PI2); ctx.fill(); ctx.stroke();
      ctx.fillStyle = '#1a1a1d';
      ctx.fillText('t=' + (1 - ts).toFixed(2), px - 16, py + (m % 2 === 0 ? -12 : 20));
    }
    ctx.fillStyle = '#1a1a1d';
    ctx.fillText('x_1 ~ N(0, I)', X(qx(0)) - 4, Y(qy(0)) + 38);
    ctx.fillText('x_0 (data)', X(qx(1)) - 50, Y(qy(1)) - 28);
    ctx.fillText('true PF-ODE trajectory', X(0.5) - 50, Tp - 22);
    // Euler phase
    var eT = Math.min(T, 4.5);
    var stepDur = 0.85;
    var nDone = Math.min(N, Math.floor(eT / stepDur));
    var frac = nDone >= N ? 0 : (eT - nDone * stepDur) / stepDur;
    if (T >= 4.5) { nDone = N; frac = 0; }
    var eAlpha = T < 5.0 ? 1 : 0.3;
    ctx.globalAlpha = eAlpha;
    ctx.strokeStyle = '#e11d48';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(X(E[0][0]), Y(E[0][1]));
    for (var k = 1; k <= nDone; k++) ctx.lineTo(X(E[k][0]), Y(E[k][1]));
    var cx = E[nDone][0], cy = E[nDone][1];
    if (nDone < N && T < 4.5) {
      var f = ease(frac);
      cx = E[nDone][0] + f * (E[nDone + 1][0] - E[nDone][0]);
      cy = E[nDone][1] + f * (E[nDone + 1][1] - E[nDone][1]);
      ctx.lineTo(X(cx), Y(cy));
    }
    ctx.stroke();
    ctx.fillStyle = '#e11d48';
    for (var k = 0; k <= nDone; k++) {
      ctx.beginPath(); ctx.arc(X(E[k][0]), Y(E[k][1]), 3.5, 0, PI2); ctx.fill();
    }
    ctx.beginPath(); ctx.arc(X(cx), Y(cy), 5, 0, PI2); ctx.fill();
    if (T >= 4.5) {
      var ex = X(E[N][0]), ey = Y(E[N][1]);
      ctx.fillText('Euler x̂_0', ex - 20, ey + 20);
      ctx.strokeStyle = '#e11d48';
      ctx.lineWidth = 1.5;
      ctx.setLineDash([3, 3]);
      ctx.beginPath(); ctx.moveTo(ex, ey); ctx.lineTo(X(qx(1)), Y(qy(1))); ctx.stroke();
      ctx.setLineDash([]);
    }
    ctx.globalAlpha = 1;
    if (T < 4.5) {
      var kk = Math.min(N, nDone + 1);
      status = 'Euler: step ' + kk + ' / ' + N + '   x ← x + h·v(x,t), h = 0.2, current t ≈ ' + (1 - (nDone + ease(frac)) / N).toFixed(2) + ' (drifts off the curve)';
    } else if (T < 5.2) {
      status = 'Euler with ' + N + ' steps ends off the trajectory: discretisation error accumulates';
    }
    // flow map phase
    var jumps = [[0, 0.5, 5.2, 6.7], [0.5, 1, 6.9, 8.4]];
    var jl = ['X_{1,0.5}', 'X_{0.5,0}'];
    if (T >= 5.2) {
      for (var j = 0; j < 2; j++) {
        var ja = jumps[j][0], jb = jumps[j][1], t0 = jumps[j][2], t1 = jumps[j][3];
        if (T < t0) continue;
        var p = ease((T - t0) / (t1 - t0));
        var ax = X(qx(ja)), ay = Y(qy(ja)), bx = X(qx(jb)), by = Y(qy(jb));
        var mx = ax + p * (bx - ax), my = ay + p * (by - ay);
        ctx.strokeStyle = '#059669';
        ctx.fillStyle = '#059669';
        ctx.lineWidth = 2;
        ctx.setLineDash([6, 4]);
        ctx.beginPath(); ctx.moveTo(ax, ay); ctx.lineTo(mx, my); ctx.stroke();
        ctx.setLineDash([]);
        if (p >= 1) {
          ctx.lineWidth = 4;
          ctx.beginPath();
          for (var i = 0; i <= 30; i++) {
            var tt = ja + (jb - ja) * i / 30;
            if (i === 0) ctx.moveTo(X(qx(tt)), Y(qy(tt))); else ctx.lineTo(X(qx(tt)), Y(qy(tt)));
          }
          ctx.globalAlpha = 0.45;
          ctx.stroke();
          ctx.globalAlpha = 1;
          ctx.lineWidth = 2;
          ctx.beginPath(); ctx.arc(bx, by, 8, 0, PI2); ctx.stroke();
        }
        ctx.beginPath(); ctx.arc(mx, my, 5, 0, PI2); ctx.fill();
        var lx = (ax + bx) / 2, ly = (ay + by) / 2;
        ctx.fillText(jl[j], lx - 20, ly + (j === 0 ? 34 : -22));
        if (T >= t0 && T < t1) {
          status = 'Flow map jump ' + (j + 1) + ' / 2:  ' + jl[j] + '(x_t) lands exactly on the trajectory,  t = ' + (1 - (ja + (jb - ja) * p)).toFixed(2);
        }
      }
      if (T >= 8.4) {
        status = 'Semigroup: X_{0.5,0} ∘ X_{1,0.5} = X_{1,0}  → 2 jumps (or 1) reach x_0 with no integration error';
      } else if (T >= 6.7 && T < 6.9) {
        status = 'Landed at t = 0.5 on the trajectory; next jump starts from there';
      }
    }
    // legend
    var ly0 = height - 40;
    ctx.lineWidth = 3;
    ctx.strokeStyle = '#e11d48'; ctx.beginPath(); ctx.moveTo(16, ly0); ctx.lineTo(40, ly0); ctx.stroke();
    ctx.fillStyle = '#1a1a1d'; ctx.fillText('Euler steps (local tangent)', 46, ly0 + 4);
    ctx.strokeStyle = '#059669'; ctx.setLineDash([6, 4]); ctx.beginPath(); ctx.moveTo(width / 2 - 20, ly0); ctx.lineTo(width / 2 + 4, ly0); ctx.stroke(); ctx.setLineDash([]);
    ctx.fillText('flow-map jump X_{t,s}, X_{t,t}=id', width / 2 + 10, ly0 + 4);
    ctx.fillStyle = '#7c3aed';
    ctx.fillText(status, 16, height - 14);
  }
};
